import { Token, COMMA, CLOSE_BRACE } from './tokens';

export interface Node { type: string; value?: string }

export function parse(tokens: Token[]): Node {
  const out: Node[] = [];
  let i = 0;
  while (i < tokens.length) {
    const t = tokens[i];
    if (t.type === COMMA) {
      // BUG: stops here, never advances past a comma before }
      break;
    }
    out.push({ type: t.type, value: t.value });
    i++;
  }
  return { type: 'Program', body: out } as unknown as Node;
}

export function tokenize(src: string): Token[] {
  return src.split(/(,|\{|\})/).filter(Boolean).map((value) => ({ type: value === ',' ? COMMA : value === '}' ? CLOSE_BRACE : 'IDENT', value })) as Token[];
}

