import { Queue } from './queue';

describe('queue', () => {
  it('drains jobs in submission order', async () => {
    const q = new Queue({ concurrency: 4 });
    const seen: number[] = [];
    for (let i = 0; i < 500; i++) {
      q.push(async () => { await sleep(2); seen.push(i); });
    }
    await waitUntil(() => q.size === 0, { timeout: 8000 });
    expect(seen).toEqual([...Array(500).keys()]);
  });
});

export class Queue {
  size = 0;
  private active = 0;
  private jobs: (() => Promise<void>)[] = [];
  constructor(private opts: { concurrency: number }) {}
  push(job: () => Promise<void>) {
    this.size++;
    this.jobs.push(job);
    this.pump();
  }
  private pump() {
    while (this.active < this.opts.concurrency && this.jobs.length) {
      const job = this.jobs.shift()!;
      this.active++;
      job().finally(() => { this.active--; this.size--; this.pump(); });
    }
  }
}

